 const [view,setView]=useState<View>('home'),[items,setItems]=useState<Medicine[]>(initial),[consent,setConsent]=useState(false),[loaded,setLoaded]=useState(false),[modal,setModal]=useState<Dialog>(null),[pending,setPending]=useState<Medicine|null>(null),[batch,setBatch]=useState(''),[staged,setStaged]=useState(false),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[error,setError]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[hi,setHi]=useState(false),[reply,setReply]=useState(''),[chatInput,setChatInput]=useState(''),[audioStatus,setAudioStatus]=useState(''),[speaking,setSpeaking]=useState(false),[showTranscript,setShowTranscript]=useState(false),[camera,setCamera]=useState(false),[mobileMenu,setMobileMenu]=useState(false),[faqOpen,setFaqOpen]=useState<number|null>(null),[draft,setDraft]=useState<Medicine>(blank),[editingKey,setEditingKey]=useState<string|null>(null),[deleteConfirm,setDeleteConfirm]=useState(false),[scanMode,setScanMode]=useState<'samples'|'upload'|'camera'|'lookup'>('camera'),[barcode,setBarcode]=useState<ParsedBarcode|null>(null),[barcodeMessage,setBarcodeMessage]=useState(''),[catalogQuery,setCatalogQuery]=useState(''),[catalogResults,setCatalogResults]=useState<CatalogRecord[]>([]),[catalogSelection,setCatalogSelection]=useState<CatalogRecord|null>(null),[catalogBusy,setCatalogBusy]=useState(false);
 const video=useRef<HTMLVideoElement>(null),stream=useRef<MediaStream|null>(null),epoch=useRef(0),gate=useRef(false),audio=useRef<HTMLAudioElement|null>(null),upload=useRef<HTMLInputElement>(null),dialog=useRef<HTMLElement|null>(null),lastFocus=useRef<HTMLElement|null>(null),audioRequest=useRef(0),scanner=useRef<BrowserMultiFormatReader|null>(null),scannerControls=useRef<IScannerControls|null>(null);
 const t=(en:string,hn:string)=>hi?hn:en;
 const active=alerts(items),isAlert=active.length>0;
