 useEffect(()=>{try{const s=restore(localStorage.getItem(STORAGE_KEY));setItems(s.items);setConsent(s.consent)}catch{setNotice('Storage is unavailable. Changes will last for this visit.')}const v=location.hash.slice(1);if(['home','cabinet','alerts','family'].includes(v))setView(v as View);setLoaded(true);const sync=()=>{const v=location.hash.slice(1);setView(['cabinet','alerts','family'].includes(v)?v as View:'home')};window.addEventListener('hashchange',sync);return()=>window.removeEventListener('hashchange',sync)},[]);
 useEffect(()=>{if(loaded)try{localStorage.setItem(STORAGE_KEY,JSON.stringify({items,consent}))}catch{setNotice('Storage is unavailable. Changes will last for this visit.')}},[items,consent,loaded]);
 useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(''),6000);return()=>clearTimeout(id)},[notice]);
 useEffect(()=>{setReply('')},[items,consent,hi]);
