 useEffect(()=>()=>{epoch.current++;audioRequest.current++;stream.current?.getTracks().forEach(tr=>tr.stop());window.speechSynthesis?.cancel();audio.current?.pause()},[]);
 function openScanner(){setScanMode('camera');setBarcode(null);setBarcodeMessage('');setCatalogQuery('');setCatalogResults([]);setCatalogSelection(null);open('scan')}
 function review(m:Medicine,stage:boolean){stopCamera();setPending(m);setStaged(stage);setBatch(stage?'DMA-2O48':m.batch);setModal('review');setError('')}
 async function handleDecoded(raw:string,format:string,stage=false){try{const m=parsePayload(raw);review(m,stage||key(m)===key(sample1));return}catch{/* A non-Carely QR or retail barcode continues through product lookup. */}const parsed=parseMedicineBarcode(raw,format);setBarcode(parsed);setBarcodeMessage(parsed.gtin?'Code read on this device. Choose “Search product by barcode” to send it to the configured catalogue.':'Code read, but it does not contain a supported product number. Search by the printed medicine name below.');setCatalogResults([]);setCatalogSelection(null);setCatalogQuery('');setScanMode('lookup');setModal('scan');stopCamera();setError('')}
 async function lookupBarcode(){if(!barcode?.gtin)return;setBarcodeMessage('Searching the barcode catalogue…');try{const res=await fetch('/api/medicine/barcode',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({gtin:barcode.gtin,batch:barcode.batch,expiry:barcode.expiry,raw:barcode.raw})});const data=await res.json() as {found?:boolean;product?:{name?:string;provider?:string};message?:string;reason?:string};if(data.found&&data.product?.name){setBarcodeMessage(`Product found in ${data.product.provider}. Search by its medicine name for composition and form.`);setCatalogQuery(data.product.name);await searchCatalogue(data.product.name);return}setBarcodeMessage(data.message|| (data.reason==='product_not_listed'?'No matching product record was found. Search by the printed medicine name below.':'Barcode read successfully; product details weren’t found. Search by the printed medicine name below.'))}catch{setBarcodeMessage('Barcode read successfully. The product lookup service could not be reached; search by the medicine name below.')}}
 async function decodeImage(src:string,stage=false){if(gate.current)return;gate.current=true;setBusy(true);setError('');const e=epoch.current;try{const reader=scanner.current??(scanner.current=new BrowserMultiFormatReader());const result=await reader.decodeFromImageUrl(src);if(e!==epoch.current)return;await handleDecoded(result.getText(),BarcodeFormat[result.getBarcodeFormat()]||String(result.getBarcodeFormat()),stage)}catch{if(e===epoch.current)setError(t('No barcode found. Use a clear, well-lit photo of the code.','बारकोड नहीं मिला। कोड की साफ़ और रोशनी वाली तस्वीर लें।'))}finally{if(e===epoch.current){gate.current=false;setBusy(false)}}}
 async function searchCatalogue(value=catalogQuery){const q=value.trim();if(q.length<2){setBarcodeMessage('Enter at least two letters to search.');return}setCatalogBusy(true);setCatalogSelection(null);try{const res=await fetch(`/api/medicine/search?q=${encodeURIComponent(q)}`);const data=await res.json() as {records?:CatalogRecord[];total?:number;error?:string;message?:string};setCatalogResults(Array.isArray(data.records)?data.records:[]);if(data.error)setBarcodeMessage(data.message||'Medicine catalogue is unavailable right now.');else setBarcodeMessage(data.records?.length?`Found ${data.total??data.records.length} matching medicine records. Choose the exact brand and manufacturer.`:'No matching record. Check the name or try its generic name.')}catch{setBarcodeMessage('Medicine catalogue is unavailable right now. Try again later.')}finally{setCatalogBusy(false)}}
 function showCatalogRecord(record:CatalogRecord){setCatalogSelection(record);setModal('catalog')}
 function useCatalogRecord(record:CatalogRecord){const strengthMatch=record.generic.match(/(\d+(?:\.\d+)?\s*(?:mg|mcg|g|ml|%)(?:\s*\/\s*\d+(?:\.\d+)?\s*(?:ml|g))?)/i);const m:Medicine={...blank,product:record.brand||record.name,manufacturer:record.manufacturer||'Unknown',strength:strengthMatch?.[1]||record.generic||'Unknown',form:record.form||'Unknown',release:'Unknown',batch:barcode?.batch||'',expiry:barcode?.expiry?.slice(0,7)||''};setDraft(m);setEditingKey(null);setModal('manual');setError('')}
 function saveScan(){if(!pending)return;const m={...pending,batch:batch.trim()};if(!m.batch){setError('Enter a batch number before saving.');return}if(staged&&m.batch!=='DMA-2048'){setError('Replace the letter O with the digit 0: DMA-2048.');return}setItems(old=>add(old,m));setPending(m);setModal('result');setError('');setNotice(items.some(x=>key(x)===key(m))?'Already saved. Your cabinet has no duplicate.':'Medicine saved to your cabinet.')}
 async function startCamera(){if(gate.current||camera)return;gate.current=true;setBusy(true);setError('');const e=epoch.current;if(!navigator.mediaDevices?.getUserMedia){setError('Camera scanning is unavailable here. Try a sample or upload a QR image.');gate.current=false;setBusy(false);return}try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280}}});if(e!==epoch.current){s.getTracks().forEach(tr=>tr.stop());return}stream.current=s;setCamera(true)}catch{if(e===epoch.current)setError('Camera access was denied or no camera is available. You can still scan a bundled sample.')}finally{if(e===epoch.current){gate.current=false;setBusy(false)}}}
 useEffect(()=>{if(!camera||!video.current||!stream.current)return;const e=epoch.current;const v=video.current;v.srcObject=stream.current;void v.play().catch(()=>{setError('Camera playback failed. Check camera permission and try again.');stopCamera()});const reader=scanner.current??(scanner.current=new BrowserMultiFormatReader());let locked=false;void reader.decodeFromVideoElement(v,(result)=>{if(!result||locked||e!==epoch.current)return;locked=true;gate.current=true;setBusy(true);void handleDecoded(result.getText(),BarcodeFormat[result.getBarcodeFormat()]||String(result.getBarcodeFormat())).finally(()=>{if(e===epoch.current){gate.current=false;setBusy(false)}})}).then(controls=>{if(e!==epoch.current)controls.stop();else scannerControls.current=controls}).catch(()=>{if(e===epoch.current)setError('No supported barcode found yet. Try moving closer, improving the light, or use an image upload.')});return()=>{scannerControls.current?.stop();scannerControls.current=null}},[camera]);
 async function fallbackAudio(request:number){try{const res=await fetch('/audio/sim-hi.mp3',{method:'HEAD'});if(request!==audioRequest.current)return;if(!res.ok||!res.headers.get('content-type')?.includes('audio'))throw Error();const a=new Audio('/audio/sim-hi.mp3');audio.current=a;a.onended=()=>setSpeaking(false);await a.play();if(request!==audioRequest.current){a.pause();return}setSpeaking(true);setAudioStatus('Playing the supplied Hindi recording.')}catch{if(request===audioRequest.current){setSpeaking(false);setAudioStatus('Hindi audio is unavailable on this device. You can read the complete transcript below.')}}}
 async function speak(){setShowTranscript(true);if(speaking){stopAudio();setAudioStatus('Playback stopped.');return}const request=++audioRequest.current;setSpeaking(true);setAudioStatus('Looking for a Hindi voice…');const synth=window.speechSynthesis;if(!synth){await fallbackAudio(request);return}let voices=synth.getVoices();if(!voices.some(v=>/^hi([-_]|$)/i.test(v.lang))){voices=await new Promise<SpeechSynthesisVoice[]>(resolve=>{const done=()=>{clearTimeout(timeout);synth.removeEventListener('voiceschanged',done);resolve(synth.getVoices())};const timeout=setTimeout(done,1200);synth.addEventListener('voiceschanged',done)})}if(request!==audioRequest.current)return;const voice=voices.find(v=>/^hi([-_]|$)/i.test(v.lang));if(!voice){await fallbackAudio(request);return}synth.cancel();const u=new SpeechSynthesisUtterance(transcript);u.lang='hi-IN';u.voice=voice;u.rate=.9;u.onend=()=>{if(request===audioRequest.current){setSpeaking(false);setAudioStatus('Hindi playback complete.')}};u.onerror=()=>{if(request===audioRequest.current)void fallbackAudio(request)};synth.speak(u);setAudioStatus('Playing in Hindi with your browser’s voice.')}
